def is_samepatterns(colors, patterns):
    if len(colors) != len(patterns):
        return False

    color_to_pattern = {}
    pattern_to_color = {}

    for i in range(len(colors)):
        color = colors[i]
        pattern_char = patterns[i]

        # Check mapping from color to pattern
        if color in color_to_pattern:
            if color_to_pattern[color] != pattern_char:
                return False
        else:
            color_to_pattern[color] = pattern_char

        # Check mapping from pattern to color
        if pattern_char in pattern_to_color:
            if pattern_to_color[pattern_char] != color:
                return False
        else:
            pattern_to_color[pattern_char] = color

    return True

