def common_in_nested_lists(nestedlist):
    if not nestedlist:
        return []

    common_set = set(nestedlist[0])

    for i in range(1, len(nestedlist)):
        current_sublist_set = set(nestedlist[i])
        common_set = common_set.intersection(current_sublist_set)

        if not common_set:
            return []

    return sorted(list(common_set), reverse=True)

