def max_product_tuple(list1):
    products_from_non_positive_tuples = []
    products_from_all_positive_tuples = []

    for tup in list1:
        product = tup[0] * tup[1]

        if tup[0] <= 0 or tup[1] <= 0:
            products_from_non_positive_tuples.append(abs(product))
        else:
            products_from_all_positive_tuples.append(product)

    if products_from_non_positive_tuples:
        return max(products_from_non_positive_tuples)
    else:
        return max(products_from_all_positive_tuples)

