import math

def parabola_focus(a, b, c):
    if a == 0:
        # If 'a' is 0, the equation y = ax^2 + bx + c becomes y = bx + c,
        # which is a linear equation, not a parabola. A linear equation
        # does not have a focus in the context of parabolic geometry.
        # Returning NaN (Not a Number) indicates an undefined result.
        return (float('nan'), float('nan'))

    focus_x = -b / (2 * a)
    focus_y = (4 * a * c - b**2 + 1) / (4 * a)

    return (focus_x, focus_y)

def check(test_id, test_val, expected):
    # Using a small tolerance for float comparisons, and handling NaN
    if isinstance(test_val, tuple) and isinstance(expected, tuple):
        assert len(test_val) == len(expected), f"Test {test_id}: Tuple length mismatch. Expected {len(expected)}, got {len(test_val)}"
        for i in range(len(test_val)):
            if math.isnan(expected[i]):
                assert math.isnan(test_val[i]), f"Test {test_id}: Expected NaN at index {i}, got {test_val[i]}"
            elif math.isinf(expected[i]):
                assert math.isinf(test_val[i]) and math.copysign(1, test_val[i]) == math.copysign(1, expected[i]), f"Test {test_id}: Expected {expected[i]} at index {i}, got {test_val[i]}"
            else:
                assert abs(test_val[i] - expected[i]) < 1e-9, f"Test {test_id}: Expected {expected[i]}, got {test_val[i]}"
    elif math.isnan(expected):
        assert math.isnan(test_val), f"Test {test_id}: Expected NaN, got {test_val}"
    elif math.isinf(expected):
        assert math.isinf(test_val) and math.copysign(1, test_val) == math.copysign(1, expected), f"Test {test_id}: Expected {expected}, got {test_val}"
    else:
        assert abs(test_val - expected) < 1e-9, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    # Test cases based on the problem description and standard mathematical definition
    check(1, parabola_focus(5, 3, 2), (-0.3, 1.6))
    check(2, parabola_focus(1, 0, 0), (0.0, 0.25)) # Parabola y = x^2
    check(3, parabola_focus(-1, 0, 0), (0.0, -0.25)) # Parabola y = -x^2
    check(4, parabola_focus(2, -4, 1), (1.0, -0.875)) # Parabola y = 2x^2 - 4x + 1
    check(5, parabola_focus(0.5, 2, 3), (-2.0, 1.5)) # Parabola y = 0.5x^2 + 2x + 3

    # Test case from the previous failure, with the mathematically correct expected value
    # y = 3x^2 + 6x + 1 => vertex x = -6/(2*3) = -1. Vertex y = 3(-1)^2 + 6(-1) + 1 = 3 - 6 + 1 = -2.
    # Focus y = -2 + 1/(4*3) = -2 + 1/12 = -24/12 + 1/12 = -23/12
    check(6, parabola_focus(3, 6, 1), (-1.0, -23/12)) 

    # Corner case: a = 0 (not a parabola)
    check(7, parabola_focus(0, 1, 2), (float('nan'), float('nan'))) # y = x + 2 (a line)
    check(8, parabola_focus(0, 0, 5), (float('nan'), float('nan'))) # y = 5 (a horizontal line)

def longest_common_subsequence(X, Y, m, n):
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if X[i - 1] == Y[j - 1]:
                dp[i][j] = 1 + dp[i - 1][j - 1]
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
    return dp[m][n]


def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

