def max_volume(s):
    q = s // 3
    r = s % 3

    if r == 0:
        return q * q * q
    elif r == 1:
        # Sides are q, q, q+1
        return q * q * (q + 1)
    else:  # r == 2
        # Sides are q, q+1, q+1
        return q * (q + 1) * (q + 1)

