    check(1, max_volume(8), 18)
    check(2, max_volume(3), 1)
    check(3, max_volume(7), 12)
    check(4, max_volume(9), 27)
    check(5, max_volume(5), 4)
    check(6, max_volume(10), 36)
    # Additional corner case: minimum valid sum for positive integer sides
    check(7, max_volume(4), 2) # q=1, r=1 -> 1*1*(1+1) = 2
    check(8, max_volume(6), 8) # q=2, r=0 -> 2*2*2 = 8

