def sum_gp(a,n,r):
    if n == 0:
        return 0
    if r == 1:
        return a * n
    else:
        return int(a * (r**n - 1) / (r - 1))

def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, sum_gp(1, 5, 2), 31)
    check(2, sum_gp(2, 3, 3), 26)
    check(3, sum_gp(5, 4, 1), 20)
    check(4, sum_gp(10, 1, 5), 10)
    check(5, sum_gp(3, 2, 4), 15)
    check(6, sum_gp(5, 0, 2), 0) # n=0 terms
    check(7, sum_gp(0, 5, 2), 0) # a=0
    check(8, sum_gp(5, 3, 0), 5) # r=0 (series: 5, 0, 0. Sum = 5)
    check(9, sum_gp(-1, 3, 2), -7) # negative a (series: -1, -2, -4. Sum = -7)
    check(10, sum_gp(1, 3, -2), 3) # negative r (series: 1, -2, 4. Sum = 3)

