import math

def is_not_prime(n):
    if n <= 1:
        return True
    if n == 2:
        return False
    if n % 2 == 0:
        return True

    for i in range(3, int(math.sqrt(n)) + 1, 2):
        if n % i == 0:
            return True

    return False


def check(test_id, test_val, expected):
    assert test_val == expected, f"Test {test_id}: Expected {expected}, got {test_val}"

def main():
    check(1, is_not_prime(2), False)
    check(2, is_not_prime(4), True)
    check(3, is_not_prime(7), False)
    check(4, is_not_prime(9), True)
    check(5, is_not_prime(1), True)
    check(6, is_not_prime(0), True)
    check(7, is_not_prime(11), False)
    check(8, is_not_prime(15), True)
    check(9, is_not_prime(29), False)

